//! Parity tests for `Date`: each program's result must equal what upstream `@opencode/codemode` (running on
//! Bun/JavaScriptCore) printed for it in the same host time zone. Cases are ported from the upstream stdlib, parity,
//! callbacks, date-test262, string-date-methods-test262, and JSON/coercion suites, plus probes of construction,
//! `Date.parse` (a corpus of common formats and a fuzz sample, V8's parser as shipped by Bun), the string forms,
//! getters and setters (coercion order, snapshots, invalid dates, TimeClip), receivers, and local-time behavior in
//! zones with daylight saving time and historical offsets.

use std::sync::Arc;

use oc_codemode::codemode::{CodeMode, ExecutionLimits};
use oc_codemode::host::NoTools;
use serde_json::Value as Json;

/// JSON equality with numbers compared as doubles (an integral result may be an integer or a float).
fn same(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Number(x), Json::Number(y)) => x.as_f64() == y.as_f64(),
        (Json::Array(x), Json::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q)),
        (Json::Object(x), Json::Object(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|((k, v), (l, w))| k == l && same(v, w))
        }
        _ => a == b,
    }
}

/// Runs every `(program, upstream result JSON)` pair and reports all mismatches at once.
fn check(cases: &[(&str, &str)]) {
    let runtime = CodeMode::new(Vec::new(), Arc::new(NoTools), Vec::new(), ExecutionLimits::default()).unwrap();
    let mut failures = Vec::new();
    for (code, expected) in cases {
        let actual = runtime.execute_blocking(code).to_json();
        let expected: Json = serde_json::from_str(expected).expect("expected JSON");
        if !same(&actual, &expected) {
            failures.push(format!("program: {code}\n  expected: {expected}\n  actual:   {actual}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n\n{}", failures.len(), cases.len(), failures.join("\n\n"));
}

use std::sync::Mutex;

/// The host time zone is process-wide: tests take turns, each pinning `TZ` for its programs (every execution runs on
/// a fresh interpreter thread, which reads the zone anew).
static ZONE: Mutex<()> = Mutex::new(());

fn in_zone(zone: &str, cases: &[(&str, &str)]) {
    let _guard = ZONE.lock().unwrap_or_else(|e| e.into_inner());
    if zone != "UTC" && !std::path::Path::new("/usr/share/zoneinfo").join(zone).exists() {
        eprintln!("skipping {zone}: no tz database entry on this host");
        return;
    }
    // SAFETY: every test in this binary serializes on ZONE before touching the environment or running programs.
    unsafe { std::env::set_var("TZ", zone) };
    check(cases);
}

